mapper.select:
SELECT
payload_json
FROM
ha_conversation_history
WHERE
owner_key = #{ownerKey}
AND record_type = #{recordType}
AND record_id = #{recordId}
AND session_id = #{sessionId}
AND turn_id = #{turnId}

mapper.update:
UPDATE ha_conversation_history
SET
timeline_sequence = history_sequence,
timeline_payload_json = #{timelinePayloadJson},
timeline_created_at = #{timelineCreatedAt}
WHERE
owner_key = #{ownerKey}
AND record_type = #{recordType}
AND record_id = #{recordId}
AND session_id = #{sessionId}
AND turn_id = #{turnId}
AND timeline_sequence IS NULL

mapper.select:
SELECT
*,
COALESCE(timeline_sequence, history_sequence) AS event_sequence
FROM
ha_conversation_history
WHERE
owner_key = #{ownerKey}
AND record_type = #{recordType}
AND record_id = #{recordId}
AND session_id = #{sessionId}
AND turn_id = #{turnId}
